RiffleLowerV2.WitnessSpec.value:
fun {k N K : ℕ} (cuts : TimeProfile.Cuts k N K) (hN : 0 < N) (eta rho chiGood : ℝ)
    (W : RiffleLowerV2.ColdWitnessData) =>
  have s := W.s N;
  have u := W.u N;
  have b := RiffleLowerV2.beta cuts hN s;
  have jp := RiffleLowerV2.J cuts hN W.theta s u;
  have hp := RiffleLowerV2.H cuts hN W.theta s u;
  have jt := RiffleLowerV2.J cuts hN 2 u (RiffleLowerV2.horizon N K);
  have ht := RiffleLowerV2.H cuts hN 2 u (RiffleLowerV2.horizon N K);
  have h := b - jp + hp;
  have gamma := 2 * b - 2 * jp - 2 * jt + hp + ht;
  W.bridgeLength = ⌈2 * rho * TimeProfile.logScale N⌉₊ ∧
    W.ms ≤ W.mu ∧
      W.mu + W.bridgeLength ≤ K ∧
        W.theta ∈ Set.Icc 3 4 ∧
          (∃ (gL : Fin K) (gR : Fin K),
              W.mu ≤ ↑gL ∧
                ↑gL < ↑gR ∧
                  ↑gR < W.mu + W.bridgeLength ∧
                    TimeProfile.GoodColumn (cuts.profile hN gL) chiGood ∧
                      TimeProfile.GoodColumn (cuts.profile hN gR) chiGood) ∧
            eta / 2 ≤ RiffleLowerV2.F cuts hN W.theta s u ∧
              jp ≤ b / 2 - 3 * RiffleLowerV2.kappa eta ∧
                (W.theta = 3 ∨ b / 2 - 5 * RiffleLowerV2.kappa eta ≤ jp) ∧
                  RiffleLowerV2.kappa eta ≤ h ∧
                    hp ≤ b - jp - RiffleLowerV2.kappa eta ∧
                      RiffleLowerV2.kappa eta ≤ gamma - h / 2 ∧
                        b - jp - jt ≤ RiffleLowerV2.beta cuts hN (RiffleLowerV2.horizon N K) ∧
                          RiffleLowerV2.beta cuts hN (RiffleLowerV2.horizon N K) < RiffleLowerV2.kappa0 eta

